// The form's answers are keyed by placeholder key. The box for a
// repeating section becomes a list of rows: one row per line, its
// columns separated by "|" in the order the section's fields are listed.
const template = $('Get the template').first().json;
const values = { ...$input.first().json };

for (const group of template.groups ?? []) {
  const text = String(values[group.key] ?? '').trim();
  delete values[group.key];
  if (!text) continue;
  values[group.key] = text
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const cells = line.split('|').map((cell) => cell.trim());
      return Object.fromEntries(group.fields.map((field, i) => [field.key, cells[i] ?? '']));
    });
}

return [{ json: values }];
